const json = (data, status = 200) => new Response(JSON.stringify(data), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "private, no-store", "x-content-type-options":"nosniff", "referrer-policy":"no-referrer" }
});

function identity(request) {
  const id = request.headers.get("oai-authenticated-user-id");
  if (!id) return null;
  const email = request.headers.get("oai-authenticated-user-email") || "";
  const encoded = request.headers.get("oai-authenticated-user-full-name") || "";
  let name = encoded || email.split("@")[0] || "Usuário NexCell";
  if (request.headers.get("oai-authenticated-user-full-name-encoding") === "percent-encoded-utf-8") {
    try { name = decodeURIComponent(encoded); } catch {}
  }
  return { id, email, name };
}

async function ensureProfile(env, user) {
  const existing = await env.DB.prepare("SELECT p.id,p.email,p.full_name,r.name role FROM profiles p JOIN roles r ON r.id=p.role_id WHERE p.id=? AND p.active=1").bind(user.id).first();
  if (existing) return existing;
  const count = await env.DB.prepare("SELECT COUNT(*) total FROM profiles").first();
  const role = Number(count?.total || 0) === 0 ? "admin" : "operator";
  await env.DB.prepare("INSERT INTO profiles (id,email,full_name,role_id) VALUES (?,?,?,?)").bind(user.id,user.email,user.name,role).run();
  return { id:user.id, email:user.email, full_name:user.name, role: role === "admin" ? "Administrador" : "Operador" };
}

const clean = (value, max = 240) => typeof value === "string" ? value.trim().slice(0,max) : "";
const cents = value => Math.round(Number(value) * 100);
const required = (value, name) => { const result=clean(value,160); if(!result) throw new Error(`${name} é obrigatório.`); return result; };
const audit = (env, profile, action, type, id, metadata={}) => env.DB.prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,metadata_json) VALUES(?,?,?,?,?)").bind(profile.id,action,type,id,JSON.stringify(metadata));

async function catalogApi(request, env, url, profile) {
  if (url.pathname === "/api/categories" && request.method === "GET") {
    const rows=await env.DB.prepare("SELECT id,name FROM categories WHERE active=1 ORDER BY name").all();
    return json({items:rows.results||[]});
  }
  if (url.pathname === "/api/suppliers" && request.method === "GET") {
    const q=`%${clean(url.searchParams.get("q")||"",80)}%`;
    const rows=await env.DB.prepare("SELECT s.*,COUNT(DISTINCT p.id) product_count FROM suppliers s LEFT JOIN products p ON p.supplier_id=s.id WHERE (s.name LIKE ? OR COALESCE(s.email,'') LIKE ?) GROUP BY s.id ORDER BY s.active DESC,s.name").bind(q,q).all();
    return json({items:rows.results||[]});
  }
  if (url.pathname === "/api/suppliers" && request.method === "POST") {
    const b=await request.json().catch(()=>null); if(!b) return json({error:"Dados inválidos."},422);
    let name; try{name=required(b.name,"Nome")}catch(e){return json({error:e.message},422)}
    const id=crypto.randomUUID();
    await env.DB.batch([
      env.DB.prepare("INSERT INTO suppliers(id,name,phone,whatsapp,email,city,state,lead_time_days,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)").bind(id,name,clean(b.phone,30)||null,clean(b.whatsapp,30)||null,clean(b.email,120)||null,clean(b.city,80)||null,clean(b.state,2).toUpperCase()||null,Math.max(0,Number(b.leadTime)||0),clean(b.notes,1200)||null,profile.id),
      audit(env,profile,"supplier.created","supplier",id,{name})
    ]);
    return json({id},201);
  }
  const supplierMatch=url.pathname.match(/^\/api\/suppliers\/([^/]+)$/);
  if(supplierMatch && request.method === "PATCH"){
    const b=await request.json().catch(()=>null); if(!b)return json({error:"Dados inválidos."},422);
    const current=await env.DB.prepare("SELECT * FROM suppliers WHERE id=?").bind(supplierMatch[1]).first(); if(!current)return json({error:"Fornecedor não encontrado."},404);
    const active=b.active===undefined?current.active:(b.active?1:0);
    await env.DB.batch([
      env.DB.prepare("UPDATE suppliers SET name=?,phone=?,whatsapp=?,email=?,city=?,state=?,lead_time_days=?,notes=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(clean(b.name,160)||current.name,clean(b.phone,30)||null,clean(b.whatsapp,30)||null,clean(b.email,120)||null,clean(b.city,80)||null,clean(b.state,2).toUpperCase()||null,Math.max(0,Number(b.leadTime)||0),clean(b.notes,1200)||null,active,current.id),
      audit(env,profile,"supplier.updated","supplier",current.id,{active})
    ]); return json({ok:true});
  }
  if (url.pathname === "/api/products" && request.method === "GET") {
    const q=`%${clean(url.searchParams.get("q")||"",80)}%`,category=clean(url.searchParams.get("category")||"",80);
    const rows=await env.DB.prepare(`SELECT p.id,p.name,p.description,p.brand,p.active,p.category_id,c.name category_name,s.name supplier_name,s.id supplier_id,v.id variant_id,v.sku,v.barcode,v.compatible_model,v.color,v.cost_cents,v.sale_price_cents,v.minimum_stock,v.active variant_active,COALESCE(ib.physical,0) physical,COALESCE(ib.reserved,0) reserved,pi.object_key image_key FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN product_variants v ON v.product_id=p.id LEFT JOIN inventory_balances ib ON ib.variant_id=v.id LEFT JOIN product_images pi ON pi.product_id=p.id WHERE (p.name LIKE ? OR COALESCE(v.sku,'') LIKE ?) AND (?='' OR p.category_id=?) ORDER BY p.active DESC,p.name,v.sku`).bind(q,q,category,category).all();
    return json({items:rows.results||[]});
  }
  if (url.pathname === "/api/products" && request.method === "POST") {
    const b=await request.json().catch(()=>null); if(!b)return json({error:"Dados inválidos."},422);
    let name; try{name=required(b.name,"Nome")}catch(e){return json({error:e.message},422)}
    if(!Array.isArray(b.variants)||!b.variants.length)return json({error:"Adicione ao menos uma variação/SKU."},422);
    const productId=crypto.randomUUID(), statements=[];
    statements.push(env.DB.prepare("INSERT INTO products(id,name,description,category_id,brand,supplier_id,created_by) VALUES(?,?,?,?,?,?,?)").bind(productId,name,clean(b.description,1600)||null,clean(b.categoryId,80)||null,clean(b.brand,80)||null,clean(b.supplierId,80)||null,profile.id));
    const seen=new Set();
    for(const raw of b.variants){
      const sku=clean(raw.sku,80).toUpperCase(); if(!sku||seen.has(sku))return json({error:"Cada variação precisa de um SKU único."},422); seen.add(sku);
      const cost=cents(raw.cost),price=cents(raw.price),opening=Math.max(0,Math.trunc(Number(raw.openingStock)||0)),minimum=Math.max(0,Math.trunc(Number(raw.minimumStock)||0));
      if(!Number.isFinite(cost)||cost<0||!Number.isFinite(price)||price<0)return json({error:`Valores inválidos no SKU ${sku}.`},422);
      const variantId=crypto.randomUUID();
      statements.push(env.DB.prepare("INSERT INTO product_variants(id,product_id,sku,barcode,compatible_model,color,cost_cents,sale_price_cents,minimum_stock) VALUES(?,?,?,?,?,?,?,?,?)").bind(variantId,productId,sku,clean(raw.barcode,80)||null,clean(raw.model,120)||null,clean(raw.color,80)||null,cost,price,minimum));
      statements.push(env.DB.prepare("INSERT INTO inventory_balances(variant_id,physical,reserved) VALUES(?,?,0)").bind(variantId,opening));
      if(opening>0)statements.push(env.DB.prepare("INSERT INTO inventory_movements(id,variant_id,movement_type,quantity,physical_after,reserved_after,reason,reference_type,reference_id,created_by) VALUES(?,?,'opening',?,?,0,'Saldo inicial','product',?,?)").bind(crypto.randomUUID(),variantId,opening,opening,productId,profile.id));
    }
    statements.push(audit(env,profile,"product.created","product",productId,{name,variants:b.variants.length}));
    try{await env.DB.batch(statements)}catch(e){return json({error:String(e).includes("UNIQUE")?"SKU ou código de barras já cadastrado.":"Não foi possível cadastrar o produto."},409)}
    return json({id:productId},201);
  }
  const productMatch=url.pathname.match(/^\/api\/products\/([^/]+)$/);
  if(productMatch && request.method === "PATCH"){
    const b=await request.json().catch(()=>null);if(!b)return json({error:"Dados inválidos."},422);
    const current=await env.DB.prepare("SELECT * FROM products WHERE id=?").bind(productMatch[1]).first();if(!current)return json({error:"Produto não encontrado."},404);
    const active=b.active===undefined?current.active:(b.active?1:0);
    await env.DB.batch([env.DB.prepare("UPDATE products SET name=?,description=?,category_id=?,brand=?,supplier_id=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(clean(b.name,160)||current.name,b.description===undefined?current.description:clean(b.description,1600)||null,b.categoryId===undefined?current.category_id:clean(b.categoryId,80)||null,b.brand===undefined?current.brand:clean(b.brand,80)||null,b.supplierId===undefined?current.supplier_id:clean(b.supplierId,80)||null,active,current.id),audit(env,profile,"product.updated","product",current.id,{active})]);return json({ok:true});
  }
  const duplicateMatch=url.pathname.match(/^\/api\/products\/([^/]+)\/duplicate$/);
  if(duplicateMatch&&request.method==="POST"){
    const source=await env.DB.prepare("SELECT * FROM products WHERE id=?").bind(duplicateMatch[1]).first();if(!source)return json({error:"Produto não encontrado."},404);
    const variants=await env.DB.prepare("SELECT * FROM product_variants WHERE product_id=?").bind(source.id).all(),id=crypto.randomUUID(),suffix=Date.now().toString().slice(-5),statements=[env.DB.prepare("INSERT INTO products(id,name,description,category_id,brand,supplier_id,created_by) VALUES(?,?,?,?,?,?,?)").bind(id,`${source.name} (cópia)`,source.description,source.category_id,source.brand,source.supplier_id,profile.id)];
    for(const v of variants.results||[]){const vid=crypto.randomUUID();statements.push(env.DB.prepare("INSERT INTO product_variants(id,product_id,sku,barcode,compatible_model,color,cost_cents,sale_price_cents,minimum_stock) VALUES(?,?,?,?,?,?,?,?,?)").bind(vid,id,`${v.sku}-C${suffix}`,null,v.compatible_model,v.color,v.cost_cents,v.sale_price_cents,v.minimum_stock),env.DB.prepare("INSERT INTO inventory_balances(variant_id,physical,reserved) VALUES(?,0,0)").bind(vid));}
    statements.push(audit(env,profile,"product.duplicated","product",id,{source:source.id}));await env.DB.batch(statements);return json({id},201);
  }
  const imageMatch=url.pathname.match(/^\/api\/products\/([^/]+)\/image$/);
  if(imageMatch&&request.method==="PUT"){
    const type=request.headers.get("content-type")||"";if(!["image/jpeg","image/png","image/webp"].includes(type))return json({error:"Use JPG, PNG ou WebP."},415);
    const bytes=await request.arrayBuffer();if(bytes.byteLength>4*1024*1024)return json({error:"A imagem deve ter até 4 MB."},413);
    const key=`products/${imageMatch[1]}/${crypto.randomUUID()}`;await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:type}});const id=crypto.randomUUID();await env.DB.batch([env.DB.prepare("INSERT INTO product_images(id,product_id,object_key,content_type,alt_text) VALUES(?,?,?,?,?)").bind(id,imageMatch[1],key,type,"Foto do produto"),audit(env,profile,"product.image_added","product",imageMatch[1],{imageId:id})]);return json({key},201);
  }
  return null;
}

async function purchasingApi(request,env,url,profile){
  if(url.pathname==="/api/purchases"&&request.method==="GET"){
    return json({items:await createPurchasingModule(env.DB).summaries()});
  }
  if(url.pathname==="/api/purchases"&&request.method==="POST"){
    const b=await request.json().catch(()=>null);if(!b||!Array.isArray(b.items)||!b.items.length)return json({error:"Adicione ao menos um item à compra."},422);
    const supplier=await env.DB.prepare("SELECT id FROM suppliers WHERE id=? AND active=1").bind(clean(b.supplierId,80)).first();if(!supplier)return json({error:"Fornecedor inválido."},422);
    const id=crypto.randomUUID(),number=`CMP-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${id.slice(0,5).toUpperCase()}`,statements=[];let subtotal=0;
    for(const item of b.items){const variant=await env.DB.prepare("SELECT id FROM product_variants WHERE id=? AND active=1").bind(clean(item.variantId,80)).first();const quantity=Math.trunc(Number(item.quantity)),cost=cents(item.unitCost);if(!variant||quantity<=0||!Number.isFinite(cost)||cost<0)return json({error:"Produto, quantidade ou custo inválido."},422);subtotal+=quantity*cost;}
    const discount=Math.max(0,cents(b.discount)||0),freight=Math.max(0,cents(b.freight)||0),other=Math.max(0,cents(b.otherCosts)||0),total=Math.max(0,subtotal-discount+freight+other);
    statements.push(env.DB.prepare("INSERT INTO purchase_orders(id,number,supplier_id,order_date,expected_date,order_status,discount_cents,freight_cents,other_costs_cents,total_cents,notes,created_by) VALUES(?,?,?,?,?,'confirmed',?,?,?,?,?,?)").bind(id,number,supplier.id,clean(b.orderDate,10)||new Date().toISOString().slice(0,10),clean(b.expectedDate,10)||null,discount,freight,other,total,clean(b.notes,1200)||null,profile.id));
    for(const item of b.items)statements.push(env.DB.prepare("INSERT INTO purchase_order_items(id,purchase_order_id,variant_id,quantity,unit_cost_cents) VALUES(?,?,?,?,?)").bind(crypto.randomUUID(),id,clean(item.variantId,80),Math.trunc(Number(item.quantity)),cents(item.unitCost)));
    statements.push(audit(env,profile,"purchase.created","purchase_order",id,{number,totalCents:total}));await env.DB.batch(statements);return json({id,number,totalCents:total},201);
  }
  const detail=url.pathname.match(/^\/api\/purchases\/([^/]+)\/items$/);
  if(detail&&request.method==="GET"){
    const rows=await env.DB.prepare(`SELECT poi.id,poi.variant_id,poi.quantity,poi.received_quantity,poi.damaged_quantity,poi.unit_cost_cents,p.name product_name,pv.sku,pv.color,pv.compatible_model FROM purchase_order_items poi JOIN product_variants pv ON pv.id=poi.variant_id JOIN products p ON p.id=pv.product_id WHERE poi.purchase_order_id=? ORDER BY p.name,pv.sku`).bind(detail[1]).all();return json({items:rows.results||[]});
  }
  const payment=url.pathname.match(/^\/api\/purchases\/([^/]+)\/payments$/);
  if(payment&&request.method==="POST"){
    try{const result=await createPurchasingModule(env.DB).recordPayment(payment[1],await request.json(),profile.id);return json({ok:true,status:result.payment_status})}catch(error){if(error instanceof PurchasingError)return json({error:error.message},error.status);throw error}
  }
  const receipt=url.pathname.match(/^\/api\/purchases\/([^/]+)\/receipts$/);
  if(receipt&&request.method==="POST"){
    try{return json(await createPurchasingModule(env.DB).confirmReceipt(receipt[1],await request.json(),profile.id),201)}catch(error){if(error instanceof PurchasingError)return json({error:error.message},error.status);throw error}
  }
  if(url.pathname==="/api/inventory"&&request.method==="GET"){
    return json({items:await createInventoryModule(env.DB).balances()});
  }
  if(url.pathname==="/api/inventory/movements"&&request.method==="GET"){
    return json({items:await createInventoryModule(env.DB).recentMovements()});
  }
  return null;
}

async function salesApi(request,env,url,profile){
  const sales=createSalesModule(env.DB);
  try{
    if(url.pathname==="/api/sales"&&request.method==="GET")return json({items:await sales.list()});
    if(url.pathname==="/api/sales"&&request.method==="POST")return json(await sales.create(await request.json(),profile.id),201);
    const items=url.pathname.match(/^\/api\/sales\/([^/]+)\/items$/);if(items&&request.method==="GET")return json({items:await sales.items(items[1])});
    const payment=url.pathname.match(/^\/api\/sales\/([^/]+)\/payments$/);if(payment&&request.method==="POST")return json(await sales.pay(payment[1],await request.json(),profile.id));
    const shipment=url.pathname.match(/^\/api\/sales\/([^/]+)\/shipments$/);if(shipment&&request.method==="POST")return json(await sales.ship(shipment[1],await request.json(),profile.id));
    const cancel=url.pathname.match(/^\/api\/sales\/([^/]+)\/cancel$/);if(cancel&&request.method==="POST")return json(await sales.cancel(cancel[1],await request.json(),profile.id));
    const returned=url.pathname.match(/^\/api\/sales\/([^/]+)\/returns$/);if(returned&&request.method==="POST")return json(await sales.returnChecked(returned[1],await request.json(),profile.id),201);
  }catch(error){if(error instanceof SalesError)return json({error:error.message},error.status);throw error}
  return null;
}

async function financeApi(request,env,url,profile){
  const finance=createFinanceModule(env.DB);
  try{
    if(url.pathname==="/api/finance"&&request.method==="GET")return json(await finance.overview());
    if(url.pathname==="/api/finance/categories"&&request.method==="GET")return json({items:await finance.categories()});
    if(url.pathname==="/api/finance/obligations"&&request.method==="GET")return json(await finance.obligations());
    if(url.pathname==="/api/finance/accounts"&&request.method==="POST")return json(await finance.createAccount(await request.json(),profile.id),201);
    if(url.pathname==="/api/finance/transactions"&&request.method==="POST")return json(await finance.createTransaction(await request.json(),profile.id),201);
    if(url.pathname==="/api/finance/transfers"&&request.method==="POST")return json(await finance.transfer(await request.json(),profile.id),201);
    const reconciliation=url.pathname.match(/^\/api\/finance\/transactions\/([^/]+)\/reconcile$/);if(reconciliation&&request.method==="POST")return json(await finance.reconcile(reconciliation[1],profile.id));
  }catch(error){if(error instanceof FinanceError)return json({error:error.message},error.status);throw error}
  return null;
}

async function pricingApi(request,env,url,profile){
  try{
    if(url.pathname==="/api/pricing/calculate"&&request.method==="POST")return json(calculatePricing(await request.json()));
    const apply=url.pathname.match(/^\/api\/pricing\/variants\/([^/]+)\/apply$/);if(apply&&request.method==="POST")return json(await createPricingModule(env.DB).apply(apply[1],await request.json(),profile.id));
  }catch(error){if(error instanceof PricingError)return json({error:error.message},error.status);throw error}
  return null;
}

async function reportingApi(request,env,url){
  const reporting=createReportingModule(env.DB);
  try{
    if(url.pathname==="/api/dashboard"&&request.method==="GET")return json(await reporting.dashboard());
    if(url.pathname==="/api/reports"&&request.method==="GET")return json(await reporting.report(clean(url.searchParams.get("type"),40),Object.fromEntries(url.searchParams)));
  }catch(error){if(error instanceof ReportingError)return json({error:error.message},error.status);throw error}
  return null;
}

async function api(request, env, url) {
  const user = identity(request);
  if (!user) return json({ error:"Autenticação necessária." }, 401);
  const profile = await ensureProfile(env, user);
  if(["POST","PUT","PATCH","DELETE"].includes(request.method)){
    const origin=request.headers.get("origin");
    if(origin&&origin!==url.origin)return json({error:"Origem da requisição não autorizada."},403);
    const adminOnly=[/^\/api\/settings$/, /^\/api\/(products|suppliers)(\/|$)/, /^\/api\/finance\/(accounts|transactions|transfers)(\/|$)/, /^\/api\/pricing\/variants\//];
    if(profile.role!=="Administrador"&&adminOnly.some(pattern=>pattern.test(url.pathname)))return json({error:"Apenas administradores podem executar esta ação."},403);
  }
  const catalogResponse=await catalogApi(request,env,url,profile); if(catalogResponse)return catalogResponse;
  const purchasingResponse=await purchasingApi(request,env,url,profile); if(purchasingResponse)return purchasingResponse;
  const salesResponse=await salesApi(request,env,url,profile); if(salesResponse)return salesResponse;
  const financeResponse=await financeApi(request,env,url,profile); if(financeResponse)return financeResponse;
  const pricingResponse=await pricingApi(request,env,url,profile); if(pricingResponse)return pricingResponse;
  const reportingResponse=await reportingApi(request,env,url); if(reportingResponse)return reportingResponse;
  if (url.pathname === "/api/session") return json({ user:profile });
  if (url.pathname === "/api/settings" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT key,value_json,updated_at FROM settings ORDER BY key").all();
    return json({ settings:(rows.results || []).map(r => ({...r,value:JSON.parse(r.value_json)})) });
  }
  if (url.pathname === "/api/settings" && request.method === "PUT") {
    if (profile.role !== "Administrador") return json({ error:"Apenas administradores podem alterar configurações." },403);
    const body = await request.json().catch(() => null);
    if (!body || typeof body.key !== "string" || body.key.length > 80 || typeof body.value !== "object") return json({ error:"Dados inválidos." },422);
    const value = JSON.stringify(body.value);
    await env.DB.batch([
      env.DB.prepare("INSERT INTO settings(key,value_json,updated_by,updated_at) VALUES(?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP").bind(body.key,value,profile.id),
      env.DB.prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,metadata_json) VALUES(?,'settings.updated','setting',?,?)").bind(profile.id,body.key,JSON.stringify({key:body.key}))
    ]);
    return json({ ok:true });
  }
  return json({ error:"Rota não encontrada." },404);
}

