function page() {
  const nav = [
    ['Visão geral','dashboard','Dashboard'],['Gestão','box','Produtos'],['','truck','Fornecedores'],['','cart','Compras'],['','stock','Recebimentos'],['','stock','Estoque'],
    ['Operação','sale','Vendas'],['','wallet','Financeiro'],['','calc','Calculadora'],['Análise','report','Relatórios'],['Administração','settings','Configurações']
  ].map(([group,ic,label],i)=>`${group?`<p class="nav-group">${group}</p>`:''}<button class="nav-item ${i===0?'active':''}" data-page="${label}">${icon(ic)}<span>${label}</span></button>`).join('');
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexCell ERP</title><meta name="description" content="Gestão interna NexCell"><style>${css}</style></head><body>
  <div class="shell"><aside id="sidebar"><div class="brand"><div class="nmark"><i></i><i></i></div><div class="wordmark"><strong>Nex<span>Cell</span></strong><small>GESTÃO</small></div></div><nav>${nav}</nav><div class="aside-foot"><div class="user"><span id="avatar">NC</span><div><strong id="userName">Carregando...</strong><small id="userRole">Sessão segura</small></div></div><a href="/signout-with-chatgpt?return_to=/" target="_top">Sair</a></div></aside>
  <main><header><button class="mobile" id="menu">${icon('menu')}</button><div><small>Operação NexCell</small><h1 id="title">Dashboard</h1></div><div class="header-actions"><label class="search">${icon('search')}<input id="search" placeholder="Buscar no sistema"><kbd>⌘ K</kbd></label><button class="round">${icon('bell')}<i></i></button><div class="profile"><span id="topAvatar">NC</span><div><strong id="topName">NexCell</strong><small id="topRole">Conta segura</small></div></div></div></header><section id="app"><div class="loading-row"></div></section></main></div>
  <div class="toast" id="toast" role="status"></div><script>${client}</script></body></html>`;
}

