const operationsCss=`.summary-strip{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid #e7ecf3;border-radius:16px;margin-bottom:16px}.summary-strip div{padding:17px;border-right:1px solid #edf1f5}.summary-strip div:last-child{border:0}.summary-strip small{display:block;color:#8a96a6;font-size:8px;margin-bottom:7px}.summary-strip strong{font-size:17px}.purchase-items{display:grid;gap:8px}.purchase-item{display:grid;grid-template-columns:1fr 90px 110px 34px;gap:8px}.purchase-item select,.purchase-item input{min-width:0;height:39px;border:1px solid #dfe6ed;border-radius:9px;padding:0 9px;font-size:9px;background:#fff}.purchase-item button{border:0;border-radius:8px;background:#feeeee;color:#dc2626}.receipt-line{display:grid;grid-template-columns:1fr 80px 80px;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid #edf1f5}.receipt-line strong{font-size:10px}.receipt-line small{display:block;color:#8a96a6;font-size:8px}.receipt-line input{height:38px;border:1px solid #dfe6ed;border-radius:9px;padding:0 8px;width:100%}.movement{font-size:8px;color:#647184}.movement b{color:#17283c}.state-draft{background:#f1f3f6;color:#687587}.state-partial{background:#fff4dd;color:#a76500}.state-paid,.state-received{background:#eaf8ef;color:#16813d}@media(max-width:700px){.summary-strip{grid-template-columns:1fr 1fr}.summary-strip div:nth-child(2){border-right:0}.purchase-item{grid-template-columns:1fr 1fr}.receipt-line{grid-template-columns:1fr 70px 70px}}`;
