const pricingClient=`let pricingMode='profit',pricingResult=null,pricingTimer;function pricingShell(){return '<div class="module-head"><div><h2>Calculadora de preço</h2><p>Transforme custos e taxas em uma margem de contribuição sustentável.</p></div></div><div class="pricing-layout"><form class="pricing-sheet" id="pricingForm"><div class="field"><label>Produto cadastrado (opcional)</label><select name="variantId" id="pricingVariant"><option value="">Cálculo livre</option></select></div><div class="mode-switch" role="tablist"><button type="button" class="active" data-pricing-mode="profit">Lucro em reais</button><button type="button" data-pricing-mode="margin">Margem percentual</button><button type="button" data-pricing-mode="simulation">Simular preço</button></div><div class="cost-grid"><h3>Custos por unidade</h3><div class="field"><label>Custo de compra</label><input name="purchaseCost" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Frete de aquisição</label><input name="acquisitionFreight" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Embalagem</label><input name="packaging" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Frete pago pela loja</label><input name="storeFreight" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label>Outros custos</label><input name="otherCosts" type="number" min="0" step="0.01" value="0"></div><h3>Taxas sobre o preço</h3><div class="field"><label>Taxa de pagamento (%)</label><input name="paymentRate" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Comissão (%)</label><input name="commissionRate" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Impostos estimados (%)</label><input name="taxRate" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Preço atual</label><input name="currentPrice" type="number" min="0" step="0.01" value="0" readonly></div><h3>Objetivo</h3><div class="field full mode-field" data-mode-field="profit"><label>Quanto deseja ganhar por unidade?</label><input name="desiredProfit" type="number" min="0" step="0.01" value="0"></div><div class="field full mode-field" data-mode-field="margin" hidden><label>Margem desejada sobre a venda (%)</label><input name="desiredMargin" type="number" min="0" step="0.01" value="30"></div><div class="field full mode-field" data-mode-field="simulation" hidden><label>Preço que deseja simular</label><input name="manualPrice" type="number" min="0.01" step="0.01" value="0"></div></div></form><aside class="price-result" id="pricingResult"><div class="empty"><strong>Preencha os custos</strong><p>O preço, as taxas e a margem aparecerão aqui.</p></div></aside></div>'}async function setupPricing(){app.innerHTML=pricingShell();const products=await getJson('/api/products').catch(()=>({items:[]})),variants=products.items.filter((x,i,a)=>x.variant_id&&x.active&&x.variant_active&&a.findIndex(y=>y.variant_id===x.variant_id)===i);window.pricingVariants=variants;$('#pricingVariant').insertAdjacentHTML('beforeend',variants.map(x=>'<option value="'+x.variant_id+'">'+esc(x.name)+' · '+esc(x.sku)+'</option>').join(''));$('#pricingForm').addEventListener('input',()=>{clearTimeout(pricingTimer);pricingTimer=setTimeout(runPricing,180)});$('#pricingVariant').onchange=e=>{const v=variants.find(x=>x.variant_id===e.target.value);if(v){$('#pricingForm [name=purchaseCost]').value=(v.cost_cents/100).toFixed(2);$('#pricingForm [name=currentPrice]').value=(v.sale_price_cents/100).toFixed(2)}else $('#pricingForm [name=currentPrice]').value='0';runPricing()};document.querySelectorAll('[data-pricing-mode]').forEach(b=>b.onclick=()=>{pricingMode=b.dataset.pricingMode;document.querySelectorAll('[data-pricing-mode]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-mode-field]').forEach(x=>x.hidden=x.dataset.modeField!==pricingMode);runPricing()});runPricing()}async function runPricing(){const form=$('#pricingForm');if(!form)return;const payload=Object.fromEntries(new FormData(form));payload.mode=pricingMode;try{const r=await fetch('/api/pricing/calculate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),o=await r.json();if(!r.ok)throw new Error(o.error);pricingResult={...o,payload,selectedPriceCents:o.commercial99Cents};renderPricing()}catch(e){pricingResult=null;$('#pricingResult').innerHTML='<div class="empty"><strong>Cálculo inviável</strong><p>'+esc(e.message)+'</p></div>'}}function renderPricing(){const x=pricingResult,margin=(x.marginBps/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';$('#pricingResult').innerHTML='<div class="price-ticket"><small>'+(pricingMode==='simulation'?'Resultado da simulação':'Preço calculado')+'</small><strong>'+money(x.priceCents)+'</strong><p>Ponto de equilíbrio: '+money(x.breakEvenCents)+'</p></div><div class="price-breakdown"><div class="price-line"><span>Custos fixos</span><strong>'+money(x.fixedCostsCents)+'</strong></div><div class="price-line"><span>Taxas proporcionais</span><strong>'+money(x.feesCents)+'</strong></div><div class="price-line"><span>Margem de contribuição</span><strong class="'+(x.contributionCents>=0?'positive':'')+'">'+money(x.contributionCents)+' · '+margin+'</strong></div><div class="price-line"><span>Diferença do preço atual</span><strong>'+money(x.differenceCents)+'</strong></div><div class="commercial-options"><button type="button" data-commercial="'+x.commercial90Cents+'">'+money(x.commercial90Cents)+'</button><button type="button" class="selected" data-commercial="'+x.commercial99Cents+'">'+money(x.commercial99Cents)+'</button></div><button type="button" class="apply-price" id="applyPrice" '+(x.payload.variantId?'':'disabled')+'>'+(x.payload.variantId?'Aplicar preço ao SKU':'Selecione um SKU para aplicar')+'</button><p class="formula-note">Margem de contribuição estimada não é lucro líquido. Despesas fixas e custos não informados ainda precisam ser considerados.</p></div>';document.querySelectorAll('[data-commercial]').forEach(b=>b.onclick=()=>{pricingResult.selectedPriceCents=Number(b.dataset.commercial);document.querySelectorAll('[data-commercial]').forEach(x=>x.classList.toggle('selected',x===b))});$('#applyPrice').onclick=applyCalculatedPrice}async function applyCalculatedPrice(){const x=pricingResult;if(!x?.payload.variantId)return;if(!confirm('Aplicar '+money(x.selectedPriceCents)+' ao produto selecionado? Vendas anteriores não serão alteradas.'))return;const payload={...x.payload,selectedPrice:(x.selectedPriceCents/100).toFixed(2)},r=await fetch('/api/pricing/variants/'+x.payload.variantId+'/apply',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),o=await r.json();if(!r.ok)return toast(o.error);$('#pricingForm [name=currentPrice]').value=(o.priceCents/100).toFixed(2);toast('Preço aplicado ao SKU.');runPricing()}const phase5Open=openPage;openPage=function(name){if(name==='Calculadora'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupPricing()}return phase5Open(name)};`;
