const reportingClient=`function dashboardShell(){return '<div class="module-head"><div><h2>Visão operacional</h2><p id="dashboardPeriod">Dados reais do período atual.</p></div><button class="secondary-action" data-page="Relatórios">Abrir relatórios</button></div><div class="real-metrics" id="realMetrics"></div><div class="dashboard-grid"><section class="panel wide-chart"><div class="panel-head"><div><h3>Faturamento diário</h3><p>Vendas confirmadas, sem pedidos cancelados.</p></div></div><div id="dailyChart"></div></section><section class="panel"><div class="panel-head"><div><h3>Alertas</h3><p>Pendências que precisam de ação.</p></div></div><div class="alert-stack" id="dashboardAlerts"></div></section></div><div class="dashboard-lower"><section class="panel"><div class="panel-head"><div><h3>Movimento financeiro</h3><p>Realizado e compromissos em aberto.</p></div></div><div class="finance-ledger" id="dashboardFinance"></div></section><section class="panel"><div class="panel-head"><div><h3>Produtos mais vendidos</h3><p>Ranking do mês por unidades.</p></div></div><div class="product-rank" id="topProducts"></div></section></div>'}async function setupDashboard(){app.innerHTML=dashboardShell();try{const d=await getJson('/api/dashboard'),m=d.metrics;$('#dashboardPeriod').textContent='Período: '+d.period.from+' a '+d.period.to;const metric=(label,value,help)=>'<article><small>'+label+'</small><strong>'+value+'</strong><p>'+help+'</p></article>';$('#realMetrics').innerHTML=metric('Faturamento',money(m.revenue_cents),'Vendas do mês')+metric('Resultado estimado',money(m.result_cents),'Faturamento − CMV − despesas')+metric('Vendas',Number(m.sales_count),'Pedidos válidos')+metric('Saldo disponível',money(m.balance_cents),'Contas financeiras')+metric('Estoque a custo',money(m.inventory_value_cents),'Valor físico')+metric('Estoque crítico',Number(m.critical_count),'SKUs no mínimo');renderDailyChart(d.daily);const alerts=[...(d.alerts.critical||[]).map(x=>({page:'Estoque',title:x.name+' · '+x.sku,detail:'Disponível '+x.available+', mínimo '+x.minimum_stock})),...(d.alerts.purchases||[]).map(x=>({page:'Recebimentos',title:'Compra '+x.number,detail:'Aguardando recebimento'})),...(d.alerts.shipping||[]).map(x=>({page:'Vendas',title:'Venda '+x.number,detail:'Envio pendente · '+x.customer_name})),...(d.alerts.due||[]).map(x=>({page:'Financeiro',title:x.description,detail:'Vence '+x.due_date+' · '+money(x.amount_cents)}))];$('#dashboardAlerts').innerHTML=alerts.length?alerts.slice(0,9).map(x=>'<button class="alert-row" data-page="'+x.page+'"><i></i><span><strong>'+esc(x.title)+'</strong><small>'+esc(x.detail)+'</small></span></button>').join(''):'<div class="empty"><strong>Nenhuma pendência agora</strong><p>Alertas surgem conforme as operações são registradas.</p></div>';$('#dashboardFinance').innerHTML='<div><span>Entradas recebidas</span><strong>'+money(d.finance.inflow_cents)+'</strong></div><div><span>Saídas pagas</span><strong>'+money(d.finance.outflow_cents)+'</strong></div><div><span>Contas a receber</span><strong>'+money(d.finance.receivable_cents)+'</strong></div><div><span>Contas a pagar</span><strong>'+money(d.finance.payable_cents)+'</strong></div>';$('#topProducts').innerHTML=d.topProducts.length?d.topProducts.map(x=>'<article>'+(x.image_key?'<img src="/images/'+encodeURIComponent(x.image_key)+'" alt="">':'<div class="product-thumb"></div>')+'<strong>'+esc(x.name)+'</strong><small>'+esc(x.sku)+' · '+x.units+' un.<br>'+money(x.revenue_cents)+'</small></article>').join(''):'<div class="empty"><strong>Sem vendas no mês</strong><p>O ranking aparece após registrar vendas.</p></div>'}catch(e){app.innerHTML='<div class="placeholder"><h2>Dashboard indisponível</h2><p>'+esc(e.message)+'</p></div>'}}function renderDailyChart(rows){const el=$('#dailyChart');if(!rows.length){el.innerHTML='<div class="chart-empty"><div><strong>Sem faturamento no período</strong><br>Registre vendas para formar a curva diária.</div></div>';return}const max=Math.max(...rows.map(x=>Number(x.revenue_cents)),1),points=rows.map((x,i)=>[(i/(Math.max(rows.length-1,1))*720)+10,210-(Number(x.revenue_cents)/max*175)]),line=points.map(p=>p.join(',')).join(' '),area='10,220 '+line+' '+points.at(-1)[0]+',220';el.innerHTML='<svg class="sales-chart" viewBox="0 0 740 230" role="img" aria-label="Faturamento diário"><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0bc7fc" stop-opacity=".32"/><stop offset="1" stop-color="#0bc7fc" stop-opacity="0"/></linearGradient></defs><line x1="10" y1="220" x2="730" y2="220" stroke="#e5ebf1"/><polygon points="'+area+'" fill="url(#salesFill)"/><polyline points="'+line+'" fill="none" stroke="#029cf9" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'+points.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="#fff" stroke="#029cf9" stroke-width="2"/>').join('')+'</svg><div class="chart-labels"><span>'+esc(rows[0].date)+'</span><strong>'+money(max)+'</strong><span>'+esc(rows.at(-1).date)+'</span></div>'}const reportNames={revenue:'Faturamento por período','sales-product':'Vendas por produto',result:'Resultado estimado','purchases-supplier':'Compras por fornecedor','margin-sku':'Margem por SKU','top-products':'Produtos mais vendidos','slow-products':'Produtos com baixo giro','inventory-value':'Valor do estoque','expenses-category':'Despesas por categoria','cash-flow':'Fluxo financeiro'};let reportRows=[];function reportsShell(){const today=new Date().toISOString().slice(0,10),from=today.slice(0,7)+'-01';return '<div class="module-head"><div><h2>Relatórios</h2><p>Filtros aplicados diretamente aos dados operacionais.</p></div></div><form class="report-filters" id="reportFilters"><select name="type">'+Object.entries(reportNames).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select><input name="from" type="date" value="'+from+'" title="Data inicial"><input name="to" type="date" value="'+today+'" title="Data final"><select name="product"><option value="">Todos os produtos</option></select><select name="category"><option value="">Todas as categorias</option></select><select name="supplier"><option value="">Todos os fornecedores</option></select><select name="status"><option value="">Todos os status</option><option value="created">Criada</option><option value="shipped">Enviada</option><option value="cancelled">Cancelada</option></select><button>Gerar</button></form><div class="report-actions"><p id="reportDescription">Escolha os filtros e gere o relatório.</p><button id="exportCsv" disabled>Exportar CSV</button></div><div class="data-table" style="border-radius:16px"><table id="reportTable"><tbody><tr><td class="table-empty">Nenhum relatório gerado.</td></tr></tbody></table></div>'}async function setupReports(){app.innerHTML=reportsShell();const [products,categories,suppliers]=await Promise.all([getJson('/api/products').catch(()=>({items:[]})),getJson('/api/categories').catch(()=>({items:[]})),getJson('/api/suppliers').catch(()=>({items:[]}))]),unique=products.items.filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);const form=$('#reportFilters');unique.forEach(x=>form.product.insertAdjacentHTML('beforeend','<option value="'+x.id+'">'+esc(x.name)+'</option>'));categories.items.forEach(x=>form.category.insertAdjacentHTML('beforeend','<option value="'+x.id+'">'+esc(x.name)+'</option>'));suppliers.items.forEach(x=>form.supplier.insertAdjacentHTML('beforeend','<option value="'+x.id+'">'+esc(x.name)+'</option>'));form.onsubmit=e=>{e.preventDefault();loadReport()};$('#exportCsv').onclick=exportReportCsv;loadReport()}async function loadReport(){const form=$('#reportFilters'),params=new URLSearchParams(new FormData(form));try{const d=await getJson('/api/reports?'+params);reportRows=d.rows;$('#reportDescription').textContent=reportNames[d.type]+' · '+d.rows.length+' linha(s)';$('#exportCsv').disabled=!d.rows.length;renderReportTable(d.rows)}catch(e){toast(e.message)}}function humanKey(key){return key.replace(/_cents$/,'').replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())}function reportValue(key,value){if(key.endsWith('_cents'))return money(value);if(key.endsWith('_bps'))return (Number(value)/100).toFixed(2)+'%';return value??'—'}function renderReportTable(rows){const table=$('#reportTable');if(!rows.length){table.innerHTML='<tbody><tr><td class="table-empty">Nenhum dado encontrado para os filtros selecionados.</td></tr></tbody>';return}const keys=Object.keys(rows[0]);table.innerHTML='<thead><tr>'+keys.map(k=>'<th>'+esc(humanKey(k))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+keys.map(k=>'<td class="'+(k.endsWith('_cents')?'money':'')+'">'+esc(reportValue(k,row[k]))+'</td>').join('')+'</tr>').join('')+'</tbody>'}function exportReportCsv(){if(!reportRows.length)return;const keys=Object.keys(reportRows[0]),quote=v=>'"'+String(v??'').replaceAll('"','""')+'"',csv='\ufeff'+[keys.map(humanKey),...reportRows.map(r=>keys.map(k=>reportValue(k,r[k])))].map(row=>row.map(quote).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='nexcell-relatorio-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url)}const phase6Open=openPage;openPage=function(name){if(name==='Dashboard'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupDashboard()}if(name==='Relatórios'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupReports()}return phase6Open(name)};openPage('Dashboard');`;
