const supabaseAuthClient=`(()=>{const nativeFetch=window.fetch.bind(window);let config=null;const saved=()=>{try{return JSON.parse(localStorage.getItem('nexcell.supabase.session')||'null')}catch{return null}};window.fetch=(input,init={})=>{const url=typeof input==='string'?input:input.url;if(url.startsWith('/api/')&&url!=='/api/config'){const token=saved()?.access_token;if(token)init={...init,headers:{...(init.headers||{}),authorization:'Bearer '+token}}}return nativeFetch(input,init)};async function getConfig(){if(config)return config;const r=await nativeFetch('/api/config');config=await r.json();if(!r.ok)throw new Error(config.error);return config}function gate(){if(document.querySelector('.auth-gate'))return;document.body.insertAdjacentHTML('beforeend','<div class="auth-gate"><form class="auth-card" id="authForm"><div class="auth-brand">Nex<span>Cell</span></div><p>Entre com sua conta segura. O primeiro cadastro confirmado será o administrador.</p><label>E-mail</label><input name="email" type="email" autocomplete="email" required><label>Senha</label><input name="password" type="password" autocomplete="current-password" minlength="6" required><button name="action" value="login">Entrar</button><button class="secondary" name="action" value="signup">Criar primeira conta</button><p class="auth-message" id="authMessage"></p></form></div>');document.querySelector('#authForm').onsubmit=authenticate}async function authenticate(e){e.preventDefault();const submit=e.submitter?.value||'login',data=Object.fromEntries(new FormData(e.currentTarget)),message=document.querySelector('#authMessage');message.textContent='Conectando...';try{const c=await getConfig(),path=submit==='signup'?'/auth/v1/signup':'/auth/v1/token?grant_type=password',r=await nativeFetch(c.url+path,{method:'POST',headers:{apikey:c.publishableKey,'content-type':'application/json'},body:JSON.stringify({email:data.email,password:data.password})}),out=await r.json();if(!r.ok)throw new Error(out.msg||out.error_description||out.message||'Não foi possível autenticar.');if(!out.access_token){message.textContent='Cadastro criado. Confirme o e-mail e depois clique em Entrar.';return}localStorage.setItem('nexcell.supabase.session',JSON.stringify(out));location.reload()}catch(error){message.textContent=error.message}}async function boot(){try{await getConfig();const token=saved()?.access_token;if(token){const r=await window.fetch('/api/session');if(r.ok)return;localStorage.removeItem('nexcell.supabase.session')}gate()}catch(error){gate();document.querySelector('#authMessage').textContent=error.message}}document.addEventListener('click',e=>{const link=e.target.closest('.aside-foot>a');if(!link)return;e.preventDefault();localStorage.removeItem('nexcell.supabase.session');location.reload()});boot()})();`;
const secureAuthClient=`(()=>{const nativeFetch=window.fetch.bind(window);let refreshing=false;window.fetch=async(input,init={})=>{const url=typeof input==='string'?input:input.url,options={...init,credentials:'same-origin'};let response=await nativeFetch(input,options);if(response.status===401&&url.startsWith('/api/')&&!url.startsWith('/api/auth/')&&!refreshing){refreshing=true;try{const refreshed=await nativeFetch('/api/auth/refresh',{method:'POST',credentials:'same-origin'});if(refreshed.ok)response=await nativeFetch(input,options)}finally{refreshing=false}}return response};function authShell(content){document.querySelector('.auth-gate')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="auth-gate"><div class="auth-card">'+content+'</div></div>')}function loginGate(message=''){authShell('<form id="authForm"><div class="auth-brand">Nex<span>Cell</span></div><p>Entre com a conta criada pelo administrador da NexCell.</p><label>E-mail</label><input name="email" type="email" autocomplete="email" required><label>Senha</label><input name="password" type="password" autocomplete="current-password" minlength="8" required><button>Entrar</button><p class="auth-message" id="authMessage">'+message+'</p></form>');document.querySelector('#authForm').onsubmit=login}async function login(e){e.preventDefault();const message=document.querySelector('#authMessage'),data=Object.fromEntries(new FormData(e.currentTarget));message.textContent='Conectando...';const r=await nativeFetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),out=await r.json();if(!r.ok){message.textContent=out.error;return}if(out.mfaRequired)return mfaGate(out);location.reload()}async function mfaGate(state={}){let factorId=state.factorId,qr='',secret='';if(state.enrollmentRequired){const enrolled=await nativeFetch('/api/auth/mfa/enroll',{method:'POST',credentials:'same-origin'}),data=await enrolled.json();if(!enrolled.ok)return loginGate(data.error);factorId=data.id;secret=data.secret||'';qr=data.qrCode||'';if(qr.startsWith('<svg'))qr='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(qr)}authShell('<form id="mfaForm"><div class="auth-brand">Verificação em duas etapas</div><p>'+(state.enrollmentRequired?'Escaneie o QR Code no aplicativo autenticador e informe o código.':'Informe o código do seu aplicativo autenticador.')+'</p>'+(qr?'<img alt="QR Code para autenticação" style="display:block;max-width:190px;margin:15px auto" src="'+qr+'">':'')+(secret?'<p style="word-break:break-all">Chave manual: '+secret+'</p>':'')+'<label>Código de 6 dígitos</label><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required><button>Confirmar código</button><p class="auth-message" id="authMessage"></p></form>');document.querySelector('#mfaForm').onsubmit=async e=>{e.preventDefault();const message=document.querySelector('#authMessage'),code=new FormData(e.currentTarget).get('code'),r=await nativeFetch('/api/auth/mfa/verify',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({factorId,code})}),out=await r.json();if(!r.ok){message.textContent=out.error;return}location.reload()}}async function boot(){const session=await window.fetch('/api/session');if(session.ok)return;const issue=await session.json().catch(()=>({}));if(issue.code==='mfa_required'){const status=await nativeFetch('/api/auth/mfa/status',{credentials:'same-origin'}),state=await status.json();if(status.ok)return mfaGate(state)}loginGate()}document.addEventListener('click',async e=>{const link=e.target.closest('.aside-foot>a');if(!link)return;e.preventDefault();await nativeFetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});location.reload()});boot().catch(()=>loginGate('Não foi possível validar a sessão.'))})();`;
