const accessUiFixesClient=`(()=>{let accessFix=null,groupUsers=[];getJson('/api/session').then(x=>accessFix=x).catch(()=>{});document.addEventListener('submit',async e=>{if(e.target.id!=='auditFilters')return;e.preventDefault();e.stopImmediatePropagation();try{const q=new URLSearchParams(new FormData(e.target)),d=await getJson('/api/admin/audit?'+q),tbody=$('#app table tbody');tbody.innerHTML=d.items.length?d.items.map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString('pt-BR')+'</td><td><strong>'+esc(x.actor_name||'Sistema')+'</strong><small>'+esc(x.actor_email||'')+'</small></td><td>'+esc(x.action)+'</td><td>'+esc(x.target_type)+'<small>'+esc(x.target_id||'')+'</small></td><td><div class="audit-delta">'+esc(JSON.stringify(x.new_value||{}))+'</div></td></tr>').join(''):'<tr><td colspan="5" class="table-empty">Nenhum registro encontrado.</td></tr>'}catch(error){toast(error.message)}},true);function alignInvites(){if(title.textContent!=='Usuários'||!window.accessUsers)return;const canInvite=accessFix?.permissions?.includes('users.invite');document.querySelectorAll('#usersBody tr').forEach(row=>{if(row.dataset.invitesAligned)return;row.dataset.invitesAligned='1';row.querySelectorAll('[data-resend-invite]').forEach(x=>x.remove());const email=row.children[1]?.textContent.trim(),user=window.accessUsers.find(x=>x.email===email);if(!user||!['pending','expired'].includes(user.invitation_status))return;row.children[3].innerHTML='<span class="state-pill state-partial">Convite '+(user.invitation_status==='expired'?'expirado':'pendente')+'</span>';const actions=row.querySelector('.row-actions');if(!actions||!canInvite)return;const b=document.createElement('button');b.dataset.resendInvite=user.invitation_id;b.textContent='Reenviar convite';b.onclick=async()=>{const r=await fetch('/api/admin/invitations/'+user.invitation_id+'/resend',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:user.email,fullName:user.name})}),o=await r.json();toast(r.ok?'Convite reenviado.':o.error)};actions.appendChild(b)})}async function auditActorFilter(){const form=$('#auditFilters');if(title.textContent!=='Logs de Auditoria'||!form||form.querySelector('[name=actor]'))return;let control='<input name="actor" placeholder="ID do usuário">';if(accessFix?.permissions?.includes('users.view')){try{const d=await getJson('/api/admin/users');control='<select name="actor"><option value="">Todos os usuários</option>'+d.items.map(x=>'<option value="'+x.id+'">'+esc(x.name||x.email)+'</option>').join('')+'</select>'}catch{}}form.insertAdjacentHTML('afterbegin',control)}async function groupUserButtons(){if(title.textContent!=='Grupos de Permissões'||!accessFix?.permissions?.includes('users.view'))return;const cards=[...document.querySelectorAll('.group-card')];if(!cards.length||cards[0].dataset.usersReady)return;if(!groupUsers.length){try{groupUsers=(await getJson('/api/admin/users')).items}catch{return}}cards.forEach(card=>{card.dataset.usersReady='1';const name=card.querySelector('h3')?.textContent,users=groupUsers.filter(u=>u.groups.some(g=>g.name===name)),area=card.querySelector('.group-actions');if(!area)return;const b=document.createElement('button');b.textContent='Ver usuários ('+users.length+')';b.onclick=()=>{document.body.insertAdjacentHTML('beforeend','<div class="drawer-shade open"><aside class="drawer"><div class="drawer-head"><div><h2>'+esc(name)+'</h2><p>Usuários associados ao grupo.</p></div><button class="drawer-close" data-close>×</button></div><div class="permission-matrix">'+(users.length?users.map(u=>'<div class="operator-order"><strong>'+esc(u.name||u.email)+'</strong><small>'+esc(u.email)+'</small></div>').join(''):'<div class="empty"><strong>Nenhum usuário associado</strong></div>')+'</div></aside></div>');document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>x.closest('.drawer-shade').remove())};area.prepend(b)})}function enhance(){setTimeout(()=>{alignInvites();auditActorFilter();groupUserButtons()},70)}new MutationObserver(enhance).observe(app,{childList:true,subtree:true});enhance()})();`;
